#!/usr/bin/env python3
"""Pixel Studio game-scene demo: "Campfire Clearing" (320×192, 16 px tiles, 8-frame loop).

Shows the game-production toolchain end to end, using only the engine's public commands:

  * three 47-tile blob autotile sets generated by the engine (`tileset_generate_blob`):
    a raised meadow plateau with a cliff lip, a dirt camp clearing and a pond;
  * tilemaps painted with ASCII terrain rows (`tilemap_terrain`) and baked onto layers;
  * hand-shaded props (pines, oaks, rocks, tent, logs) with selective outlines;
  * a multiply shadow layer and an additive glow layer (`layer_blend`);
  * the original cast from ../sprites2d (idle loops) standing around an animated campfire;
  * slices for gameplay data (hurtboxes, interact zone);
  * normal-mapped 2D lighting (`render_lit`): flickering fire, tent lantern, fireflies,
    banded into crisp pixel-art light steps at night;
  * engine exports: Tiled .tmj, tileset atlases, Godot SpriteFrames, Aseprite-style atlas.

    python3 build_level.py   ->  level.jsonl + level_showcase.jsonl
    cargo run --release --example run_script -- assets/level/level_showcase.jsonl out/level
"""

import json
import math
import os

W, H, T = 320, 192, 16
FRAMES = 8
TAU = math.tau
here = os.path.dirname(os.path.abspath(__file__))
lines = []


def cmd(op, **a):
    a = {"op": op, "actor": "level-builder", **a}
    lines.append(json.dumps(a, separators=(",", ":")))


def hx(c):
    return "#%02X%02X%02X" % tuple(max(0, min(255, round(v))) for v in c)


def rgb(h):
    h = h.lstrip("#")
    return [int(h[i:i + 2], 16) for i in (0, 2, 4)]


def mix(a, b, t):
    return [a[i] + (b[i] - a[i]) * t for i in range(3)]


def hnoise(x, y, seed=0):
    n = (x * 374761393 + y * 668265263 + seed * 1013904223) & 0xFFFFFFFF
    n = (n ^ (n >> 13)) * 1274126177 & 0xFFFFFFFF
    return ((n ^ (n >> 16)) & 0xFFFF) / 65535.0


def ramp(base, n=5, hue_cool="#2A2F6B", hue_warm="#FFF1B0"):
    """Hue-shifted ramp dark→light: shadows lean blue-violet, lights lean warm yellow."""
    b = rgb(base)
    out = []
    for i in range(n):
        t = i / (n - 1) * 2 - 1
        if t < 0:
            c = mix(b, rgb(hue_cool), -t * 0.55)
            c = [v * (1 + t * 0.35) for v in c]
        else:
            c = mix(b, rgb(hue_warm), t * 0.45)
        out.append(hx(c))
    return out


# ------------------------------------------------------------------ props (pixel dicts)

LIGHT = (-0.55, -0.65, 0.52)  # top-left, slightly above
_l = math.sqrt(sum(v * v for v in LIGHT))
LIGHT = tuple(v / _l for v in LIGHT)


def tone(n, r, bias=0.0):
    d = n[0] * LIGHT[0] + n[1] * LIGHT[1] + n[2] * LIGHT[2] + bias
    k = max(0.0, min(0.999, d * 0.5 + 0.5))
    return r[int(k * len(r))]


def oak(cx, cy, s=1.0, seed=0):
    img = {}
    leaves = ramp("#3F7F3A", 6)
    bark = ramp("#6B4A32", 4)
    for y in range(int(cy), int(cy + 12 * s)):
        for x in range(int(cx - 3 * s), int(cx + 3 * s) + 1):
            k = (x - (cx - 3 * s)) / (6 * s)
            img[(x, y)] = bark[1 if k > 0.6 else 2 if k > 0.25 else 3]
    blobs = [(0, -14, 13), (-10, -8, 9), (10, -8, 9), (-6, -20, 9), (7, -19, 9), (0, -4, 9)]
    for y in range(int(cy - 34 * s), int(cy + 4 * s)):
        for x in range(int(cx - 22 * s), int(cx + 22 * s)):
            best = None
            for bx, by, br in blobs:
                br *= s
                # Leaf clusters make the silhouette and shading lumpy, not a smooth ball.
                cell = hnoise((x - int(cx)) // 3, (y - int(cy)) // 3, seed)
                rr = br + (cell - 0.5) * 2.4
                dx, dy = x - (cx + bx * s), y - (cy + by * s)
                d2 = (dx * dx + dy * dy) / (rr * rr)
                if d2 < 1:
                    h = math.sqrt(1 - d2)
                    if best is None or h + by * 0.0 > best[0]:
                        best = (h, (dx / rr, dy / rr, h))
            if best:
                n = best[1]
                bump = (hnoise((x - int(cx)) // 2, (y - int(cy)) // 2, seed + 5) - 0.5) * 0.35
                img[(x, y)] = tone(n, leaves, bump)
    return img


def pine(cx, base, s=1.0, seed=0):
    img = {}
    needles = ramp("#2F6B4F", 5, hue_cool="#1B2550")
    bark = ramp("#5A3B2A", 3)
    for y in range(int(base - 6 * s), int(base) + 1):
        for x in range(int(cx - 2), int(cx + 2) + 1):
            img[(x, y)] = bark[2 if x > cx else 1]
    tiers = 4
    top = base - 52 * s
    for t in range(tiers):
        ty0 = top + t * 11 * s
        ty1 = ty0 + 18 * s
        half = (7 + t * 4.5) * s
        for y in range(int(ty0), int(ty1)):
            k = (y - ty0) / (ty1 - ty0)
            w = half * k
            for x in range(int(cx - w) - 1, int(cx + w) + 2):
                dx = x - cx
                if abs(dx) > w:
                    continue
                # Saw-tooth lower edge of each tier.
                if k > 0.8 and (int(abs(dx)) + int(y)) % 3 == 0:
                    continue
                side = dx / max(w, 1)
                n = (side * 0.8, -0.3 + k * 0.6, 0.6)
                c = tone(n, needles, -0.15 if k > 0.75 else 0.05)
                if hnoise(x, y, seed) > 0.86:
                    c = needles[min(4, needles.index(c) + 1)]
                img[(x, y)] = c
    return img


def rock(cx, cy, rx, ry, seed=0):
    img = {}
    stone = ramp("#7D8496", 5, hue_cool="#24284A")
    for y in range(int(cy - ry), int(cy + ry) + 1):
        for x in range(int(cx - rx), int(cx + rx) + 1):
            dx, dy = (x - cx) / rx, (y - cy) / ry
            if dy < 0:
                dy *= 1.25  # flatter top
            d = dx * dx + dy * dy
            if d > 1:
                continue
            h = math.sqrt(1 - d)
            img[(x, y)] = tone((dx, dy, h), stone, (hnoise(x, y, seed) - 0.5) * 0.3)
    return img


def tent(x0, y0):
    img = {}
    fab = ramp("#C4683F", 5)
    apex, bl, br = (x0 + 24, y0), (x0, y0 + 38), (x0 + 48, y0 + 38)
    back_apex, back_br = (x0 + 58, y0 - 6), (x0 + 74, y0 + 30)

    def inside(p, a, b, c):
        def s(p1, p2, p3):
            return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])
        d1, d2, d3 = s(p, a, b), s(p, b, c), s(p, c, a)
        return not ((d1 < 0 or d2 < 0 or d3 < 0) and (d1 > 0 or d2 > 0 or d3 > 0))

    for y in range(y0 - 8, y0 + 40):
        for x in range(x0 - 2, x0 + 78):
            p = (x + 0.5, y + 0.5)
            if inside(p, apex, back_apex, back_br) or inside(p, apex, back_br, br):
                # Side roof faces right/up: shaded, with seams running to the back.
                u = (x - x0 - 24) / 50
                c = fab[1] if (y - y0 + x // 2) % 9 == 0 else fab[2] if u < 0.5 else fab[1]
                img[(x, y)] = c
            if inside(p, apex, bl, br):
                k = (y - y0) / 38
                c = fab[3] if k < 0.5 else fab[2]
                if abs(x + 0.5 - apex[0]) < 1:
                    c = fab[1]
                img[(x, y)] = c
                door_w = 9 * max(0.0, (y - y0 - 12) / 26)
                if abs(x + 0.5 - apex[0]) < door_w:
                    img[(x, y)] = "#2A1720" if abs(x + 0.5 - apex[0]) < door_w - 2 else "#5B2E2A"
    # Ridge pole and pegs.
    for i in range(36):
        x = round(apex[0] + (back_apex[0] - apex[0]) * i / 35)
        y = round(apex[1] + (back_apex[1] - apex[1]) * i / 35)
        img[(x, y)] = fab[4]
    for px, py in [(x0 - 3, y0 + 39), (x0 + 51, y0 + 39), (x0 + 76, y0 + 31)]:
        img[(px, py)] = "#4A3426"
        img[(px, py - 1)] = "#6B4A32"
    return img


def log(cx, cy, length, seed=0):
    img = {}
    bark = ramp("#6E4A30", 4)
    for y in range(cy - 3, cy + 3):
        for x in range(cx - length // 2, cx + length // 2):
            k = (y - (cy - 3)) / 6
            c = bark[3] if k < 0.25 else bark[2] if k < 0.6 else bark[1]
            if hnoise(x // 3, y, seed) > 0.8:
                c = bark[0]
            img[(x, y)] = c
    for y in range(cy - 3, cy + 3):  # cut end with rings
        for x in range(cx + length // 2, cx + length // 2 + 3):
            r = abs(y - cy + 0.5) + (x - cx - length // 2)
            img[(x, y)] = "#D9B07A" if r < 1.6 else "#B98A58" if r < 2.6 else "#8A5E3A"
    return img


def bush(cx, cy, seed=0):
    img = {}
    g = ramp("#4C8B3E", 5)
    for y in range(cy - 7, cy + 4):
        for x in range(cx - 9, cx + 10):
            dx, dy = (x - cx) / 9, (y - cy + 1) / 7
            d = dx * dx + dy * dy + (hnoise(x // 2, y // 2, seed) - 0.5) * 0.4
            if d < 1:
                img[(x, y)] = tone((dx, dy, math.sqrt(max(0, 1 - d))), g)
    for i in range(3):
        bx, by = cx - 4 + i * 4, cy - 3 + (i % 2) * 2
        img[(bx, by)] = "#F4D6E8"  # tiny blossoms
    return img


def fire_ring(cx, cy):
    img = {}
    for i in range(10):
        a = TAU * i / 10
        img.update(rock(cx + math.cos(a) * 15, cy + math.sin(a) * 7, 3.2, 2.4, seed=i))
    for i, (dx, dy, ln) in enumerate([(-1, 1, 16), (2, 3, 14)]):
        lg = log(cx + dx, cy + dy, ln, seed=9 + i)
        img.update({k: ("#2C1A16" if v not in ("#D9B07A",) else "#5A3A2A") for k, v in lg.items()})
    return img


# ------------------------------------------------------------------ animated layers

FIRE = ["#FFF9D6", "#FFE066", "#FFA431", "#F2581F", "#B72727", "#5E1A2A"]


def vnoise(x, y, z, seed=0):
    xi, yi, zi = math.floor(x), math.floor(y), math.floor(z)
    fx, fy, fz = x - xi, y - yi, z - zi
    f = lambda t: t * t * (3 - 2 * t)  # noqa: E731
    sx, sy, sz = f(fx), f(fy), f(fz)
    acc = 0.0
    for dz in (0, 1):
        for dy in (0, 1):
            for dx in (0, 1):
                w = (sx if dx else 1 - sx) * (sy if dy else 1 - sy) * (sz if dz else 1 - sz)
                n = ((xi + dx) * 374761393 + (yi + dy) * 668265263 + (zi + dz) * 2147483647 + seed * 1013904223) & 0xFFFFFFFF
                n = (n ^ (n >> 13)) * 1274126177 & 0xFFFFFFFF
                acc += w * (((n ^ (n >> 16)) & 0xFFFF) / 65535.0)
    return acc


def loop_noise(x, y, t, period, seed=0):
    a = TAU * t / period
    return vnoise(x + 1.2 * math.cos(a), y + 1.2 * math.sin(a), 0.0, seed)


def flames(cx, base, t):
    img = {}
    for y in range(base - 34, base + 1):
        for x in range(cx - 12, cx + 13):
            h = (base - y) / 30.0
            dx = (x - cx) / 9.0
            width = max(0.0, 1 - h) ** 0.75 * (1.0 - 0.15 * math.sin(h * 6 + TAU * t / FRAMES))
            sway = 0.3 * math.sin(TAU * t / FRAMES + h * 3.5) * h
            body = 1 - abs(dx - sway) / max(width, 0.01)
            turb = loop_noise(x * 0.3, y * 0.25 + t * 0.9, t, FRAMES, 3) * 0.55 + loop_noise(x * 0.7, y * 0.6, t, FRAMES, 9) * 0.3
            v = body * 0.95 + turb * 0.55 - h * 0.6
            for th, c in zip([0.95, 0.78, 0.6, 0.42, 0.3], FIRE):
                if v >= th:
                    img[(x, y)] = c
                    break
    for i in range(7):
        p = (t / FRAMES + i * 0.137) % 1
        ex = cx + math.sin(TAU * (p + i * 0.31)) * (3 + i % 4)
        ey = base - 18 - p * 40
        img[(round(ex), round(ey))] = FIRE[1] if p < 0.5 else FIRE[3]
    return img


FIREFLIES = [(40, 150, 0.0), (70, 170, 0.3), (24, 128, 0.55), (250, 70, 0.2), (285, 92, 0.7), (230, 150, 0.45), (120, 40, 0.85), (300, 140, 0.1)]


def firefly_pos(i, t):
    x0, y0, ph = FIREFLIES[i]
    a = TAU * (t / FRAMES + ph)
    return round(x0 + math.cos(a) * 5 + math.sin(2 * a) * 2), round(y0 + math.sin(a) * 3)


def glow(cx, cy, t):
    img = {}
    r = 46 + 3 * math.sin(TAU * t / FRAMES * 2)
    for y in range(int(cy - r), int(cy + r) + 1):
        for x in range(int(cx - r * 1.4), int(cx + r * 1.4) + 1):
            d = math.hypot((x - cx) / 1.4, y - cy) / r
            if d >= 1:
                continue
            level = (1 - d) ** 1.5
            # 4×4 Bayer ordered dither keeps the falloff crisp.
            bayer = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5][(y % 4) * 4 + x % 4] / 16
            if level * 1.6 > bayer:
                img[(x, y)] = "#3A1E0C" if level < 0.45 else "#5A2E10"
    return img


# ------------------------------------------------------------------ helpers


def put(img, layer, frame=0, base=None):
    px = [[x, y, c] for (x, y), c in sorted(img.items()) if 0 <= x < W and 0 <= y < H]
    for i in range(0, len(px), 60000):
        cmd("set_pixels", layer=layer, frame=frame, pixels=px[i:i + 60000])


def ellipse_shadow(cx, cy, rx, ry):
    img = {}
    for y in range(int(cy - ry), int(cy + ry) + 1):
        for x in range(int(cx - rx), int(cx + rx) + 1):
            if ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1:
                img[(x, y)] = "#7480B4"
    return img


# ------------------------------------------------------------------ build

cmd("project_new", width=W, height=H, name="Campfire Clearing")
cmd("layer_rename", layer=0, name="Ground")
for name in ["Clearing", "Pond", "Plateau", "Shadows", "Props", "Characters", "Glow", "Fire", "Fireflies"]:
    cmd("layer_create", name=name)

# Ground: non-repeating meadow (base + blades + flowers) drawn directly.
meadow = ramp("#4A8A3E", 5)
cmd("draw_rectangle", layer="Ground", x=0, y=0, width=W, height=H, color=meadow[2], filled=True)
g = {}
for y in range(H):
    for x in range(W):
        n = hnoise(x // 6, y // 6, 3) * 0.6 + hnoise(x // 2, y // 2, 4) * 0.4
        if n > 0.78:
            g[(x, y)] = meadow[3]
        elif n < 0.2:
            g[(x, y)] = meadow[1]
        r = hnoise(x, y, 11)
        if r > 0.965:  # grass blade: 2 px, lit tip
            g[(x, y)] = meadow[4]
            g[(x, y + 1)] = meadow[3]
        elif r < 0.004:
            g[(x, y)] = ["#F6E27A", "#F4A6C8", "#BFE3FF"][int(r * 1000) % 3]
put(g, "Ground")

# Autotile sets generated by the engine.
cmd("tileset_generate_blob", name="dirt", tile_size=T, fill="#8E6E4C", accents=["#A6855E", "#73563B"], density=0.1, seed=3,
    light="#A88A64", dark="#6E5238", outline="#4E3A2E", inset=1, edge=1, rounded=True)
cmd("tileset_generate_blob", name="pond", tile_size=T, fill="#3B74B0", accents=["#5D9BD3", "#2F5E96"], density=0.08, seed=5,
    light="#9FD3F2", dark="#2B568C", outline="#1E3560", inset=1, edge=2, rounded=True)
cmd("tileset_generate_blob", name="plateau", tile_size=T, fill="#5B9A44", accents=["#78B553", "#467D37"], density=0.12, seed=8,
    light="#8CC45E", dark="#467D37", outline="#2C4A2E", inset=0, edge=1, lip=6, lip_color="#8A6446", rounded=True)

PLATEAU = [
    "####################",
    "##########.....#####",
    "######..........###.",
    "###.............##..",
    "....................",
]
CLEARING = [
    "....................",
    "....................",
    "....................",
    "....................",
    "....................",
    "......#######.......",
    ".....#########......",
    ".....##########.....",
    "......##########....",
    ".........#######....",
    "............#####...",
    ".............#####..",
]
POND = [
    "....................",
    "....................",
    "....................",
    "....................",
    "....................",
    "....................",
    "....................",
    "....................",
    ".##.................",
    "###.................",
    "####................",
    "####................",
]
for name, ts, rows, layer in [("clearing", "dirt", CLEARING, "Clearing"), ("pond", "pond", POND, "Pond"), ("plateau", "plateau", PLATEAU, "Plateau")]:
    cmd("tilemap_create", name=name, tileset=ts, columns=W // T, rows=H // T)
    cmd("tilemap_terrain", tilemap=name, rows=rows)
    cmd("tilemap_bake", tilemap=name, layer=layer, frame=0)

# Props, back to front (painter's order by base y).
FIRE_X, FIRE_Y = 168, 124
props = []
for i, (x, b) in enumerate([(14, 40), (40, 30), (70, 44), (104, 24), (128, 34), (232, 30), (262, 38), (296, 26), (318, 44), (190, 20)]):
    props.append((b, pine(x, b, 0.75 + 0.1 * (i % 3), seed=i)))
for i, (x, y) in enumerate([(292, 120), (300, 176), (12, 102)]):
    props.append((y + 10, oak(x, y, 1.0, seed=20 + i)))
props.append((118, tent(30, 82)))
for i, (x, y, rx, ry) in enumerate([(98, 150, 6, 4), (272, 104, 6, 4), (226, 170, 5, 3), (60, 66, 4, 3), (150, 70, 6, 4), (86, 132, 3, 2)]):
    props.append((y + ry, rock(x, y, rx, ry, seed=40 + i)))
for i, (x, y) in enumerate([(206, 62), (32, 132), (262, 150), (120, 168)]):
    props.append((y + 3, bush(x, y, seed=60 + i)))
props.append((FIRE_Y + 8, fire_ring(FIRE_X, FIRE_Y)))
props.append((150, log(FIRE_X, 150, 34, seed=70)))
props.sort(key=lambda p: p[0])
allp = {}
for _, img in props:
    allp.update(img)
put(allp, "Props")
cmd("outline", layer="Props", frame=0, color="selective")

# Shadows (multiply, cool blue — light from the top-left falls to the bottom-right).
sh = {}
for x, b in [(14, 40), (40, 30), (70, 44), (104, 24), (128, 34), (232, 30), (262, 38), (296, 26), (190, 20)]:
    sh.update(ellipse_shadow(x + 6, b + 2, 12, 4))
for x, y in [(292, 120), (300, 176), (12, 102)]:
    sh.update(ellipse_shadow(x + 8, y + 12, 20, 6))
sh.update(ellipse_shadow(70, 122, 40, 6))
sh.update(ellipse_shadow(FIRE_X + 2, 154, 20, 3))
for cx in (126, 214):
    sh.update(ellipse_shadow(cx + 4, 146, 11, 3))
put(sh, "Shadows")
cmd("layer_blend", layer="Shadows", mode="multiply")
cmd("layer_opacity", layer="Shadows", opacity=200)

# All static layers are done: share them across the loop (cels are reference-counted).
for f in range(1, FRAMES):
    cmd("frame_duplicate", frame=0)
for f in range(FRAMES):
    cmd("frame_set_duration", frame=f, duration=110)

# Characters from the cast (idle loops), placed at the fire.
cast = [json.loads(l) for l in open(os.path.join(here, "..", "sprites2d", "cast.jsonl")) if l.strip()]
idle = {}
for o in cast:
    if o["op"] == "draw_ascii":
        idle.setdefault(o["frame"], o)
LOOP = [0, 1, 2, 3, 3, 2, 1, 0]
for f in range(FRAMES):
    for base_frame, x, flip in [(0, 110, False), (8, 198, True), (16, 236, True)]:
        o = idle[base_frame + LOOP[(f + base_frame // 8) % FRAMES]]
        y = 96 if base_frame != 16 else 46
        cmd("draw_ascii", layer="Characters", frame=f, x=x, y=y, rows=o["rows"], legend=o["legend"], flip_x=flip)
put(ellipse_shadow(252 + 4, 96, 11, 3), "Shadows")  # third character, on the rise

# Animated fire, glow and fireflies.
for f in range(FRAMES):
    put(flames(FIRE_X, FIRE_Y + 2, f), "Fire", f)
    put(glow(FIRE_X, FIRE_Y - 4, f), "Glow", f)
    ff = {}
    for i in range(len(FIREFLIES)):
        x, y = firefly_pos(i, f)
        on = (f + i) % 4 != 0
        ff[(x, y)] = "#F2FF9A" if on else "#9BD14A"
        if on:
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ff[(x + dx, y + dy)] = "#9BD14A80"
    put(ff, "Fireflies", f)
cmd("layer_blend", layer="Glow", mode="add")

# Gameplay data: slices exported with the atlas.
cmd("slice_set", name="hurtbox_aoi", x=118, y=104, width=16, height=40, pivot=[8, 40])
cmd("slice_set", name="hurtbox_ren", x=206, y=104, width=16, height=40, pivot=[8, 40])
cmd("slice_set", name="interact_campfire", x=FIRE_X - 18, y=FIRE_Y - 12, width=36, height=24, color="#FFB000")
cmd("slice_set", name="spawn_player", x=248, y=176, width=16, height=16, pivot=[8, 16], color="#40FF80")

with open(os.path.join(here, "level.jsonl"), "w") as fh:
    fh.write("\n".join(lines) + "\n")

# ------------------------------------------------------------------ showcase renders

show = list(lines)


def save(op, name, **a):
    show.append(json.dumps({"op": op, "_save": name, **a}, separators=(",", ":")))


save("export_png", "day_albedo_x3.png", frame=0, scale=3)
save("export_gif", "day_loop_x2.gif", scale=2)
show.append(json.dumps({"op": "layer_visibility", "layer": "Glow", "visible": False}))
for f in range(FRAMES):
    flick = 2.3 + 0.35 * math.sin(TAU * f / FRAMES * 2) + 0.15 * math.sin(TAU * f / FRAMES * 3 + 1)
    lights = [
        {"x": FIRE_X + math.sin(f) * 0.8, "y": FIRE_Y - 6, "z": 26, "color": "#FFB060", "intensity": round(flick * 1.45, 3), "radius": 160},
        {"x": 54, "y": 104, "z": 14, "color": "#FFD27A", "intensity": 0.9, "radius": 44},
    ]
    for i in range(len(FIREFLIES)):
        x, y = firefly_pos(i, f)
        lights.append({"x": x, "y": y, "z": 6, "color": "#C8FF6A", "intensity": 0.45 if (f + i) % 4 else 0.1, "radius": 9})
    save("render_lit", f"night/night_{f}.png", frame=f, scale=3, lights=lights, ambient="#3E4A7C", bands=5,
         unlit_layers=["Fire", "Fireflies"], normal_strength=1.0, strength=2.5, bevel=2)
show.append(json.dumps({"op": "layer_visibility", "layer": "Glow", "visible": True}))
save("export_normal_map", "normal_map_x2.png", frame=0, scale=2, strength=2.5, bevel=2)
for ts in ("plateau", "dirt", "pond"):
    save("export_tileset", f"tileset_{ts}_x4.png", tileset=ts, scale=4)
save("export_tiled", "tiled/clearing_tileset.png", tilemap="clearing", image="clearing_tileset.png", _json=True)
save("export_godot_spriteframes", "godot/campfire.png", layer="Fire", texture_path="res://campfire.png", _json=True)
save("export_atlas", "atlas/campfire_atlas.png", layer="Fire", image="campfire_atlas.png", padding=1, extrude=1, _json=True)
save("project_save", "campfire_clearing.pxs")

with open(os.path.join(here, "level_showcase.jsonl"), "w") as fh:
    fh.write("\n".join(show) + "\n")
print(f"{len(lines)} commands -> level.jsonl ({len(show)} with showcase renders)")
